// Rest offset for an expanded detail panel anchored inside the AG Grid
// workspace. Candidate edges are measured from the live grid layout.

// Reference edge A: the top of the grid root wrapper.
function edgeA(ctx) {
  return 0;
}

// Reference edge B: the bottom of the complete pinned standing region.
function edgeB(ctx) {
  const wrapperTop = ctx.rootWrapper.getBoundingClientRect().top;
  const header = ctx.gridEl.querySelector('.ag-header');
  const floatingTop = ctx.gridEl.querySelector('.ag-floating-top');
  const bandVisible = Boolean(floatingTop) && floatingTop.offsetHeight !== 0;
  const leadingEdge = bandVisible
    ? floatingTop.getBoundingClientRect().bottom
    : header.getBoundingClientRect().bottom;
  return leadingEdge - wrapperTop;
}

// Reference edge C: the extent of the owning master row.
function edgeC(ctx) {
  return ctx.masterRow.getBoundingClientRect().height;
}

const REFERENCE_EDGE = 'A';

export function computeDetailAnchorTop(ctx) {
  switch (REFERENCE_EDGE) {
    case 'B': return edgeB(ctx);
    case 'C': return edgeC(ctx);
    default: return edgeA(ctx);
  }
}

export function applyDetailAnchor(detailEl, ctx) {
  const top = computeDetailAnchorTop(ctx);
  detailEl.style.position = 'absolute';
  detailEl.style.left = '0';
  detailEl.style.right = '0';
  detailEl.style.top = top + 'px';
  detailEl.dataset.anchorTop = String(Math.round(top));
}
