import { readFile } from 'node:fs/promises';
import { extname, join, normalize } from 'node:path';

const args = process.argv.slice(2);
const port = Number((args.includes('--port') ? args[args.indexOf('--port') + 1] : 0) || 4173);
const host = (args.includes('--host') ? args[args.indexOf('--host') + 1] : '') || '127.0.0.1';
const upstream = process.env.CUA_SWE_EXTERNAL_SERVICE_ORIGIN || 'http://127.0.0.1:4411';
const types = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css' };

http.createServer(async (req, res) => {
  if (req.url.startsWith('/api/')) {
    try {
      const upstreamRes = await fetch(upstream + req.url, { method: req.method });
      res.writeHead(upstreamRes.status, { 'content-type': upstreamRes.headers.get('content-type') || 'application/json' });
      res.end(Buffer.from(await upstreamRes.arrayBuffer()));
    } catch {
      res.writeHead(502, { 'content-type': 'application/json' });
      res.end('{"error":"workspace layout service unavailable"}');
    }
    return;
  }
  const rel = req.url === '/' ? 'index.html' : req.url.split('?')[0].slice(1);
  const safe = normalize(rel).replace(/^([.][.][/\\\\])+/, '');
  try {
    const file = await readFile(join(process.cwd(), safe));
    res.writeHead(200, { 'content-type': types[extname(safe)] || 'application/octet-stream' });
    res.end(file);
  } catch {
    const file = await readFile(join(process.cwd(), 'index.html'));
    res.writeHead(200, { 'content-type': 'text/html' });
    res.end(file);
  }
}).listen(port, host);
